<?php
require 'config.php'; require_login(); verify_csrf(); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(isset($_POST['devolver'])){$s=$pdo->prepare("UPDATE prestamos SET estado='Devuelto',fecha_retorno=CURDATE() WHERE id=? AND estado='Prestado'");$s->execute([(int)$_POST['devolver']]);flash('Devolución registrada.');}
 else{$libro=(int)$_POST['libro_id'];$lector=(int)$_POST['lector_id'];$fecha=$_POST['fecha_devolucion'];$s=$pdo->prepare('SELECT stock FROM libros WHERE id=?');$s->execute([$libro]);$stock=$s->fetchColumn();if($stock===false||$stock<1){flash('No hay ejemplares disponibles.','danger');}else{$pdo->beginTransaction();try{$pdo->prepare("INSERT INTO prestamos(libro_id,lector_id,fecha_prestamo,fecha_devolucion,estado) VALUES(?,?,CURDATE(),?,'Prestado')")->execute([$libro,$lector,$fecha]);$pdo->prepare('UPDATE libros SET stock=stock-1 WHERE id=?')->execute([$libro]);$pdo->commit();flash('Préstamo registrado.');}catch(Throwable $e){$pdo->rollBack();flash('No se pudo registrar el préstamo.','danger');}}}
 header('Location: prestamos.php');exit;
}
$books=$pdo->query('SELECT id,titulo,stock FROM libros WHERE stock>0 ORDER BY titulo')->fetchAll();$readers=$pdo->query('SELECT id,nombre FROM lectores ORDER BY nombre')->fetchAll();
$rows=$pdo->query('SELECT p.*,l.titulo,le.nombre lector FROM prestamos p JOIN libros l ON l.id=p.libro_id JOIN lectores le ON le.id=p.lector_id ORDER BY p.id DESC')->fetchAll();$pageTitle='Gestión de préstamos';require 'partials/header.php';
?>
<div class="row g-4"><div class="col-lg-4"><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-semibold">Registrar préstamo</div><div class="card-body"><form method="post"><?=csrf_field()?><div class="mb-3"><label class="form-label">Libro disponible</label><select class="form-select" name="libro_id" required><option value="">Seleccione...</option><?php foreach($books as $b):?><option value="<?=$b['id']?>"><?=e($b['titulo'])?> (stock: <?=$b['stock']?>)</option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Lector</label><select class="form-select" name="lector_id" required><option value="">Seleccione...</option><?php foreach($readers as $r):?><option value="<?=$r['id']?>"><?=e($r['nombre'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Fecha límite de devolución</label><input type="date" class="form-control" name="fecha_devolucion" min="<?=date('Y-m-d')?>" value="<?=date('Y-m-d',strtotime('+7 days'))?>" required></div><button class="btn btn-primary w-100">Registrar préstamo</button></form></div></div></div>
<div class="col-lg-8"><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-semibold">Historial de préstamos</div><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Libro / lector</th><th>Fecha préstamo</th><th>Fecha límite</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['titulo'])?></strong><div class="small text-muted"><?=e($r['lector'])?></div></td><td><?=e($r['fecha_prestamo'])?></td><td><?=e($r['fecha_devolucion'])?></td><td><span class="badge text-bg-<?=$r['estado']==='Devuelto'?'success':($r['fecha_devolucion']<date('Y-m-d')?'danger':'warning')?>"><?=e($r['estado']==='Prestado'&&$r['fecha_devolucion']<date('Y-m-d')?'Vencido':$r['estado'])?></span></td><td><?php if($r['estado']==='Prestado'):?><form method="post" onsubmit="return confirm('¿Confirmar devolución?')"><?=csrf_field()?><button class="btn btn-sm btn-outline-success" name="devolver" value="<?=$r['id']?>">Devolver</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<?php require 'partials/footer.php'; ?>
